module WordGame(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input [7:0] arr_0,\n    input [7:0] arr_1,\n    input [7:0] arr_2,\n    input [7:0] arr_3,\n    input [7:0] arr_4,\n    input [7:0] arr_5,\n    input [7:0] arr_6,\n    input [7:0] arr_7,\n    output reg win,\n    output reg [7:0] word_0,\n    output reg [7:0] word_1,\n    output reg [7:0] word_2,\n    output reg [7:0] word_3,\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE     = 2'd0;\n    localparam [1:0] PROCESS  = 2'd1;\n    localparam [1:0] DONE_ST  = 2'd2;\n\n    reg [1:0] state, next_state;\n    reg [6:0] seq_index;\n    reg [31:0] best_slavko;\n    reg found_win;\n\n    // Round choice decomposition\n    wire [2:0] round1_sel = seq_index / 3'd15;\n    wire [4:0] round1_mod = seq_index % 3'd15;\n    wire [2:0] round2_sel = round1_mod[4:2] / 3'd3;\n    wire [1:0] round3_sel = round1_mod[1:0];\n\n    // Simulation signals\n    reg [2:0] slav_picks [0:3];\n    reg [2:0] mirko_picks [0:3];\n    reg [7:0] current_mask;\n    wire [31:0] current_slav_word;\n    wire [31:0] current_mirko_word;\n    wire current_win;\n    wire [3:0][7:0] slav_arr;\n    wire [3:0][7:0] mirr_arr;\n\n    // Highest set bit function\n    function [2:0] find_highest;\n        input [7:0] mask;\n        integer i;\n        begin\n            find_highest = 3'd0;\n            for (i = 7; i >= 0; i = i - 1) begin\n                if (mask[i]) begin\n                    find_highest = 3'(i);\n                    break;\n                end\n            end\n        end\n    endfunction\n\n    // I-th set bit function (ascending order)\n    function [2:0] find_ith_bit;\n        input [7:0] mask;\n        input [2:0] idx;\n        reg [2:0] cnt;\n        integer i;\n        begin\n            cnt = 3'd0;\n            find_ith_bit = 3'd0;\n            for (i = 0; i <= 7; i = i + 1) begin\n                if (mask[i]) begin\n                    if (cnt == idx) begin\n                        find_ith_bit = 3'(i);\n                    end\n                    cnt = cnt + 3'd1;\n                end\n            end\n        end\n    endfunction\n\n    // Simulation combinational logic\n    always @(*) begin\n        current_mask = 8'b11111111;\n        \n        // Round 1\n        mirko_picks[0] = find_highest(current_mask);\n        current_mask[mirko_picks[0]] = 1'b0;\n        slav_picks[0] = find_ith_bit(current_mask, round1_sel);\n        current_mask[slav_picks[0]] = 1'b0;\n\n        // Round 2\n        mirko_picks[1] = find_highest(current_mask);\n        current_mask[mirko_picks[1]] = 1'b0;\n        slav_picks[1] = find_ith_bit(current_mask, round2_sel);\n        current_mask[slav_picks[1]] = 1'b0;\n\n        // Round 3\n        mirko_picks[2] = find_highest(current_mask);\n        current_mask[mirko_picks[2]] = 1'b0;\n        slav_picks[2] = find_ith_bit(current_mask, {1'b0, round3_sel});\n        current_mask[slav_picks[2]] = 1'b0;\n\n        // Round 4\n        mirko_picks[3] = find_highest(current_mask);\n        current_mask[mirko_picks[3]] = 1'b0;\n        slav_picks[3] = find_ith_bit(current_mask, 3'd0);\n    end\n\n    // ASCII value mapping\n    assign slav_arr[0] = (slav_picks[0] == 3'd0) ? arr_0 :\n                        (slav_picks[0] == 3'd1) ? arr_1 :\n                        (slav_picks[0] == 3'd2) ? arr_2 :\n                        (slav_picks[0] == 3'd3) ? arr_3 :\n                        (slav_picks[0] == 3'd4) ? arr_4 :\n                        (slav_picks[0] == 3'd5) ? arr_5 :\n                        (slav_picks[0] == 3'd6) ? arr_6 : arr_7;\n    \n    assign slav_arr[1] = (slav_picks[1] == 3'd0) ? arr_0 :\n                        (slav_picks[1] == 3'd1) ? arr_1 :\n                        (slav_picks[1] == 3'd2) ? arr_2 :\n                        (slav_picks[1] == 3'd3) ? arr_3 :\n                        (slav_picks[1] == 3'd4) ? arr_4 :\n                        (slav_picks[1] == 3'd5) ? arr_5 :\n                        (slav_picks[1] == 3'd6) ? arr_6 : arr_7;\n\n    assign slav_arr[2] = (slav_picks[2] == 3'd0) ? arr_0 :\n                        (slav_picks[2] == 3'd1) ? arr_1 :\n                        (slav_picks[2] == 3'd2) ? arr_2 :\n                        (slav_picks[2] == 3'd3) ? arr_3 :\n                        (slav_picks[2] == 3'd4) ? arr_4 :\n                        (slav_picks[2] == 3'd5) ? arr_5 :\n                        (slav_picks[2] == 3'd6) ? arr_6 : arr_7;\n\n    assign slav_arr[3] = (slav_picks[3] == 3'd0) ? arr_0 :\n                        (slav_picks[3] == 3'd1) ? arr_1 :\n                        (slav_picks[3] == 3'd2) ? arr_2 :\n                        (slav_picks[3] == 3'd3) ? arr_3 :\n                        (slav_picks[3] == 3'd4) ? arr_4 :\n                        (slav_picks[3] == 3'd5) ? arr_5 :\n                        (slav_picks[3] == 3'd6) ? arr_6 : arr_7;\n\n    assign mirr_arr[0] = (mirko_picks[0] == 3'd0) ? arr_0 :\n                        (mirko_picks[0] == 3'd1) ? arr_1 :\n                        (mirko_picks[0] == 3'd2) ? arr_2 :\n                        (mirko_picks[0] == 3'd3) ? arr_3 :\n                        (mirko_picks[0] == 3'd4) ? arr_4 :\n                        (mirko_picks[0] == 3'd5) ? arr_5 :\n                        (mirko_picks[0] == 3'd6) ? arr_6 : arr_7;\n\n    assign mirr_arr[1] = (mirko_picks[1] == 3'd0) ? arr_0 :\n                        (mirko_picks[1] == 3'd1) ? arr_1 :\n                        (mirko_picks[1] == 3'd2) ? arr_2 :\n                        (mirko_picks[1] == 3'd3) ? arr_3 :\n                        (mirko_picks[1] == 3'd4) ? arr_4 :\n                        (mirko_picks[1] == 3'd5) ? arr_5 :\n                        (mirko_picks[1] == 3'd6) ? arr_6 : arr_7;\n\n    assign mirr_arr[2] = (mirko_picks[2] == 3'd0) ? arr_0 :\n                        (mirko_picks[2] == 3'd1) ? arr_1 :\n                        (mirko_picks[2] == 3'd2) ? arr_2 :\n                        (mirko_picks[2] == 3'd3) ? arr_3 :\n                        (mirko_picks[2] == 3'd4) ? arr_4 :\n                        (mirko_picks[2] == 3'd5) ? arr_5 :\n                        (mirko_picks[2] == 3'd6) ? arr_6 : arr_7;\n\n    assign mirr_arr[3] = (mirko_picks[3] == 3'd0) ? arr_0 :\n                        (mirko_picks[3] == 3'd1) ? arr_1 :\n                        (mirko_picks[3] == 3'd2) ? arr_2 :\n                        (mirko_picks[3] == 3'd3) ? arr_3 :\n                        (mirko_picks[3] == 3'd4) ? arr_4 :\n                        (mirko_picks[3] == 3'd5) ? arr_5 :\n                        (mirko_picks[3] == 3'd6) ? arr_6 : arr_7;\n\n    assign current_slav_word = {slav_arr[0], slav_arr[1], slav_arr[2], slav_arr[3]};\n    assign current_mirko_word = {mirr_arr[0], mirr_arr[1], mirr_arr[2], mirr_arr[3]};\n    assign current_win = current_slav_word < current_mirko_word;\n\n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            seq_index <= 7'd0;\n            best_slavko <= 32'hFFFF_FFFF;\n            found_win <= 1'b0;\n            win <= 1'b0;\n            {word_0, word_1, word_2, word_3} <= 32'd0;\n            done <= 1'b0;\n        end\n        else begin\n            done <= 1'b0;\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        state <= PROCESS;\n                        seq_index <= 7'd0;\n                        best_slavko <= 32'hFFFF_FFFF;\n                        found_win <= 1'b0;\n                    end\n                end\n                PROCESS: begin\n                    // Update best lex word\n                    if (current_slav_word < best_slavko) begin\n                        best_slavko <= current_slav_word;\n                    end\n                    // Update win flag\n                    if (current_win) begin\n                        found_win <= 1'b1;\n                    end\n                    // Next sequence or done\n                    if (seq_index == 7'd104) begin\n                        state <= DONE_ST;\n                    end\n                    else begin\n                        seq_index <= seq_index + 7'd1;\n                    end\n                end\n                DONE_ST: begin\n                    state <= IDLE;\n                    win <= found_win;\n                    {word_0, word_1, word_2, word_3} <= best_slavko;\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\n\nendmodule